interface ICoreComptroller {
    function getAllMarkets() external view returns (address[] memory);
    function _setMintPaused(address market, bool state) external;
    function _setBorrowPaused(address market, bool state) external;
    function _setTransferPaused(bool state) external;
    function _setSeizePaused(bool state) external;
}

interface IEcosystemComptroller {
    function getAllMarkets() external view returns (address[] memory);
    function _setMintPaused(address market, bool state) external;
    function _setBorrowPaused(address market, bool state) external;
    function _setTransferPaused(bool state) external;
    function _setSeizePaused(bool state) external;
}

interface ISAVAX {
    function pause() external;
    function pauseMinting() external;
}

interface ProofOfReserveFeed {
    function latestRoundData() external view returns (
        uint80 roundId,
        int256 answer,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    );
}

interface UnderlyingToken {
    function totalSupply() external view returns (uint256);
}

interface QiToken {
    function underlying() external view returns (address);
}

contract PauseGuardianExtended is Ownable2Step {
    ICoreComptroller public constant coreComptroller = ICoreComptroller(0x486Af39519B4Dc9a7fCcd318217352830E8AD9b4);
    IEcosystemComptroller public constant ecosystemComptroller = IEcosystemComptroller(0xD7c4006d33DA2A0A8525791ed212bbCD7Aca763F);
    ISAVAX public constant sAVAX = ISAVAX(0x2b2C81e08f1Af8835a78Bb2A90AE924ACE0eA4bE);
    address public constant benqiPauseGuardianMsig = 0x30d62267874DdA4D32Bb28ddD713f77d1aa99159;

    mapping(address => bool) public pauseGuardians;
    mapping(address => address) public proofOfReserveFeeds;
    address[] public markets;
    bool public anyoneCanPause;

    // Event emitted when a POR feed is removed
    event ProofOfReserveFeedRemoved(address indexed qiToken);

    constructor() Ownable2Step() {
        // Initialize anyoneCanPause to true so that the POR pause can be triggered by anyone
        anyoneCanPause = true;

        // Initialize pause guardians
        pauseGuardians[benqiPauseGuardianMsig] = true;
        pauseGuardians[0x6c93befC455F2A7aB47a630f97557100F219D406] = true;
        pauseGuardians[0xa401c69432e801a8A15B1938E4499d5F57438EAB] = true;
        pauseGuardians[0x32de667c77991edEFf7B6206707E31191Ef333c5] = true;
        pauseGuardians[0x6561e5F09AaE9f8823Dad9f87ccA1a38ACCF5E50] = true;
        pauseGuardians[0xee16670954F31eDfd77C1647B09E22e88b108464] = true;
        pauseGuardians[0xEd2338E3cfea0a728726B32493A1F13aE3bd1336] = true;
        pauseGuardians[0x966cd311E15F7603A6CdAb1BfcdbD450Daa17c47] = true;
        pauseGuardians[0x3277011a70081Ad3795caaE96f7d71c2F03ec301] = true;
        pauseGuardians[0x8c8E983DA404DeD4658c9FF19A1017eEC614E3D0] = true;
        pauseGuardians[0x8Cdd3725c33C302024A4FEef6012cb69ef155621] = true;

        // Initialize proof of reserve feeds ( https://docs.chain.link/data-feeds/proof-of-reserve/addresses?network=avalanche )
        _setProofOfReserveFeed(0xe194c4c5aC32a3C9ffDb358d9Bfd523a0B6d1568, 0xebEfEAA58636DF9B20a4fAd78Fad8759e6A20e87); // qiBTC.e
        _setProofOfReserveFeed(0x334AD834Cd4481BB02d09615E7c11a00579A7909, 0xDDaf9290D057BfA12d7576e6dADC109421F31948); // qiWETH.e
        _setProofOfReserveFeed(0xc9e5999b8e75C3fEB117F6f73E664b9f3C8ca65C, 0x94D8c2548018C27F1aa078A23C4158206bE1CC72); // qiUSDT.e
        _setProofOfReserveFeed(0x4e9f683A27a6BdAD3FC2764003759277e93696e6, 0x943cEF1B112Ca9FD7EDaDC9A46477d3812a382b6); // qiLINK.e
        _setProofOfReserveFeed(0x835866d37AFB8CB8F8334dCCdaf66cf01832Ff5D, 0x976D7fAc81A49FA71EF20694a3C56B9eFB93c30B); // qiDAI.e
        _setProofOfReserveFeed(0xBEb5d47A3f720Ec0a390d04b4d41ED7d9688bC7F, 0x63769951E4cfDbDC653dD9BBde63D2Ce0746e5F2); // qiUSDC.e
        _setProofOfReserveFeed(0x89a415b3D20098E6A6C8f7a59001C67BD3129821, 0x99311B4bf6D8E3D3B4b9fbdD09a1B0F4Ad8e06E9); // qiBTC.b
    }

    // Core Markets functions
    function pauseMintingAndBorrowingForAllCoreMarkets() external onlyPauseGuardian {
        address[] memory coreMarkets = coreComptroller.getAllMarkets();

        uint nofMarkets = coreMarkets.length;
        for (uint i; i < nofMarkets; ++i) {
            coreComptroller._setMintPaused(address(coreMarkets[i]), true);
            coreComptroller._setBorrowPaused(address(coreMarkets[i]), true);
        }
    }

    function pauseMintingAndBorrowingForCoreMarket(address market) external onlyPauseGuardian {
        coreComptroller._setMintPaused(market, true);
        coreComptroller._setBorrowPaused(market, true);
    }

    function pauseMintingCoreMarket(address market) external onlyPauseGuardian {
        coreComptroller._setMintPaused(market, true);
    }

    function pauseBorrowingCoreMarket(address market) external onlyPauseGuardian {
        coreComptroller._setBorrowPaused(market, true);
    }

    function pauseTransfersCore() external onlyPauseGuardian {
        coreComptroller._setTransferPaused(true);
    }

    function pauseLiquidationsCore() external onlyPauseGuardian {
        coreComptroller._setSeizePaused(true);
    }

    // Ecosystem Markets functions
    function pauseMintingAndBorrowingForAllEcosystemMarkets() external onlyPauseGuardian {
        address[] memory ecosystemMarkets = ecosystemComptroller.getAllMarkets();

        uint nofMarkets = ecosystemMarkets.length;
        for (uint i; i < nofMarkets; ++i) {
            ecosystemComptroller._setMintPaused(address(ecosystemMarkets[i]), true);
            ecosystemComptroller._setBorrowPaused(address(ecosystemMarkets[i]), true);
        }
    }

    function pauseMintingAndBorrowingForEcosystemMarket(address market) external onlyPauseGuardian {
        ecosystemComptroller._setMintPaused(market, true);
        ecosystemComptroller._setBorrowPaused(market, true);
    }

    function pauseMintingEcosystemMarket(address market) external onlyPauseGuardian {
        ecosystemComptroller._setMintPaused(market, true);
    }

    function pauseBorrowingEcosystemMarket(address market) external onlyPauseGuardian {
        ecosystemComptroller._setBorrowPaused(market, true);
    }

    function pauseTransfersEcosystem() external onlyPauseGuardian {
        ecosystemComptroller._setTransferPaused(true);
    }

    function pauseLiquidationsEcosystem() external onlyPauseGuardian {
        ecosystemComptroller._setSeizePaused(true);
    }

    // sAVAX functions
    function pauseSAVAX() external onlyPauseGuardian {
        sAVAX.pause();
    }

    function pauseMintingSAVAX() external onlyPauseGuardian {
        sAVAX.pauseMinting();
    }

    // Proof of Reserve functions
    function setProofOfReserveFeed(address qiToken, address feed) external onlyOwner {
        _setProofOfReserveFeed(qiToken, feed);
    }

    function _setProofOfReserveFeed(address qiToken, address feed) internal {
        require(feed != address(0), "Invalid feed address");

        // Sanity check: Ensure the feed has latestRoundData() function
        (
            ,  // roundId
            int256 answer,
            ,  // startedAt
            uint256 updatedAt,
            // answeredInRound
        ) = ProofOfReserveFeed(feed).latestRoundData();

        require(answer > 0, "Invalid feed: negative or zero value");
        require(updatedAt != 0, "Invalid feed: no timestamp");

        // Verify it's a qiERC20 token (will revert for qiAVAX since it has no underlying)
        require(QiToken(qiToken).underlying() != address(0), "Invalid qiERC20 token");

        if (proofOfReserveFeeds[qiToken] == address(0)) {
            markets.push(qiToken);
        }
        proofOfReserveFeeds[qiToken] = feed;
    }

    function proofOfReservesPause() public {

        if (!anyoneCanPause) {
            require(pauseGuardians[msg.sender], "Not authorized");
        }

        require(_canPause(), "Proof of reserves are OK");
        _pauseMintingAndBorrowingForAllMarkets();
    }

    // Checks if the proof of reserves is OK for all markets
    function _canPause() internal view returns (bool) {
        uint marketCount = markets.length;
        for (uint i; i < marketCount; ++i) {
            address qiTokenAddress = markets[i];
            ProofOfReserveFeed proofOfReserveFeed = ProofOfReserveFeed(proofOfReserveFeeds[qiTokenAddress]);
            uint underlyingTokenTotalSupply = UnderlyingToken(QiToken(qiTokenAddress).underlying()).totalSupply();
            (, int256 proofOfReserveAnswer, , ,) = proofOfReserveFeed.latestRoundData();
            if (underlyingTokenTotalSupply > uint256(proofOfReserveAnswer)) {
                return true;
            }
        }
        return false;
    }

    function _pauseMintingAndBorrowingForAllMarkets() internal {
        address[] memory coreMarkets = coreComptroller.getAllMarkets();
        address[] memory ecosystemMarkets = ecosystemComptroller.getAllMarkets();

        uint nofCoreMarkets = coreMarkets.length;
        for (uint i; i < nofCoreMarkets; ++i) {
            coreComptroller._setMintPaused(address(coreMarkets[i]), true);
            coreComptroller._setBorrowPaused(address(coreMarkets[i]), true);
        }

        uint nofEcosystemMarkets = ecosystemMarkets.length;
        for (uint i; i < nofEcosystemMarkets; ++i) {
            ecosystemComptroller._setMintPaused(address(ecosystemMarkets[i]), true);
            ecosystemComptroller._setBorrowPaused(address(ecosystemMarkets[i]), true);
        }
    }

    // Chainlink Automation functions
    function checkUpkeep(bytes calldata) external view returns (bool upkeepNeeded, bytes memory performData) {
        upkeepNeeded = _canPause();
        performData = new bytes(0);
    }

    function performUpkeep(bytes calldata) external {
        proofOfReservesPause();
    }

    modifier onlyPauseGuardian {
        require(pauseGuardians[msg.sender], "Not authorized");
        _;
    }

    function setAnyoneCanPause(bool flag) external {
        require(owner() == msg.sender || pauseGuardians[msg.sender], "Not authorized");
        anyoneCanPause = flag;
    }

    /**
     * @dev Removes the Proof of Reserve feed for a given market.
     * Can only be called by the owner.
     * @param qiToken The address of the QiToken whose feed is to be removed.
     */
    function removeProofOfReserveFeed(address qiToken) external onlyOwner {
        require(proofOfReserveFeeds[qiToken] != address(0), "Feed does not exist");

        // Remove the feed from the mapping
        delete proofOfReserveFeeds[qiToken];

        // Remove the qiToken from the markets array
        for (uint i = 0; i < markets.length; i++) {
            if (markets[i] == qiToken) {
                markets[i] = markets[markets.length - 1];
                markets.pop();
                break;
            }
        }

        emit ProofOfReserveFeedRemoved(qiToken);
    }
