    // Proof of Reserve functions
    function setProofOfReserveFeed(address qiToken, address feed) external onlyOwner {
        _setProofOfReserveFeed(qiToken, feed);
    }

    function _setProofOfReserveFeed(address qiToken, address feed) internal {
        require(feed != address(0), "Invalid feed address");

        // Sanity check: Ensure the feed has latestRoundData() function
        (
            ,  // roundId
            int256 answer,
            ,  // startedAt
            uint256 updatedAt,
            // answeredInRound
        ) = ProofOfReserveFeed(feed).latestRoundData();

        require(answer > 0, "Invalid feed: negative or zero value");
        require(updatedAt != 0, "Invalid feed: no timestamp");

        // Verify it's a qiERC20 token (will revert for qiAVAX since it has no underlying)
        require(QiToken(qiToken).underlying() != address(0), "Invalid qiERC20 token");

        if (proofOfReserveFeeds[qiToken] == address(0)) {
            markets.push(qiToken);
        }
        proofOfReserveFeeds[qiToken] = feed;
    }

    function proofOfReservesPause() public {

        if (!anyoneCanPause) {
            require(pauseGuardians[msg.sender], "Not authorized");
        }

        require(_canPause(), "Proof of reserves are OK");
        _pauseMintingAndBorrowingForAllMarkets();
    }

    // Checks if the proof of reserves is OK for all markets
    function _canPause() internal view returns (bool) {
        uint marketCount = markets.length;
        for (uint i; i < marketCount; ++i) {
            address qiTokenAddress = markets[i];
            ProofOfReserveFeed proofOfReserveFeed = ProofOfReserveFeed(proofOfReserveFeeds[qiTokenAddress]);
            uint underlyingTokenTotalSupply = UnderlyingToken(QiToken(qiTokenAddress).underlying()).totalSupply();
            (, int256 proofOfReserveAnswer, , ,) = proofOfReserveFeed.latestRoundData();
            if (underlyingTokenTotalSupply > uint256(proofOfReserveAnswer)) {
                return true;
            }
        }
        return false;
    }

    function _pauseMintingAndBorrowingForAllMarkets() internal {
        address[] memory coreMarkets = coreComptroller.getAllMarkets();
        address[] memory ecosystemMarkets = ecosystemComptroller.getAllMarkets();

        uint nofCoreMarkets = coreMarkets.length;
        for (uint i; i < nofCoreMarkets; ++i) {
            coreComptroller._setMintPaused(address(coreMarkets[i]), true);
            coreComptroller._setBorrowPaused(address(coreMarkets[i]), true);
        }

        uint nofEcosystemMarkets = ecosystemMarkets.length;
        for (uint i; i < nofEcosystemMarkets; ++i) {
            ecosystemComptroller._setMintPaused(address(ecosystemMarkets[i]), true);
            ecosystemComptroller._setBorrowPaused(address(ecosystemMarkets[i]), true);
        }
    }

    // Chainlink Automation functions
    function checkUpkeep(bytes calldata) external view returns (bool upkeepNeeded, bytes memory performData) {
        upkeepNeeded = _canPause();
        performData = new bytes(0);
    }

    function performUpkeep(bytes calldata) external {
        proofOfReservesPause();
    }

    modifier onlyPauseGuardian {
        require(pauseGuardians[msg.sender], "Not authorized");
        _;
    }

    function setAnyoneCanPause(bool flag) external {
        require(owner() == msg.sender || pauseGuardians[msg.sender], "Not authorized");
        anyoneCanPause = flag;
    }

    /**
     * @dev Removes the Proof of Reserve feed for a given market.
     * Can only be called by the owner.
     * @param qiToken The address of the QiToken whose feed is to be removed.
     */
    function removeProofOfReserveFeed(address qiToken) external onlyOwner {
        require(proofOfReserveFeeds[qiToken] != address(0), "Feed does not exist");

        // Remove the feed from the mapping
        delete proofOfReserveFeeds[qiToken];

        // Remove the qiToken from the markets array
        for (uint i = 0; i < markets.length; i++) {
            if (markets[i] == qiToken) {
                markets[i] = markets[markets.length - 1];
                markets.pop();
                break;
            }
        }

        emit ProofOfReserveFeedRemoved(qiToken);
    }
